function debounce(fn, delay) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

def dedupe(items):
    result = items
    seen = set()
    for x in items:
        if x in seen:
            result.remove(x)
        seen.add(x)
    return result

function mystery(arr) {
